"""Ollama-backed local LLM provider.

Talks to a local Ollama server (default http://127.0.0.1:11434) so Jarvis
can answer privately, offline, with zero per-query cost.  Uses Ollama's
HTTP /api/chat endpoint so we don't pull the `ollama` Python SDK as a
dependency — keeps the install footprint small.

Switch on by setting in `.env`:

    LLM_PROVIDER=ollama
    OLLAMA_MODEL=llama3.1:8b      # or qwen2.5:7b, mistral, etc.

Then make sure Ollama is running:

    brew install ollama
    ollama serve &
    ollama pull llama3.1:8b
"""

from __future__ import annotations

from typing import Optional

import requests

from config import settings
from utils.logger import get_logger

logger = get_logger(__name__)


class OllamaClient:
    """Chat-style wrapper that mirrors the small subset of the Groq client
    interface our `ConversationEngine` calls (`chat.completions.create`)."""

    def __init__(
        self,
        host: Optional[str] = None,
        model: Optional[str] = None,
        timeout: int = 60,
    ):
        self._host = (host or settings.OLLAMA_HOST).rstrip("/")
        self._model = model or settings.OLLAMA_MODEL
        self._timeout = timeout

    def is_available(self) -> bool:
        """Quick health check — used by the engine to decide whether to
        attempt an Ollama call at all."""
        try:
            resp = requests.get(f"{self._host}/api/tags", timeout=2)
            return resp.status_code == 200
        except Exception:
            return False

    def chat(self, messages: list[dict], max_tokens: int = 512, temperature: float = 0.7) -> str:
        """Synchronous /api/chat call.  Returns assistant's text or raises."""
        payload = {
            "model": self._model,
            "messages": messages,
            "stream": False,
            "options": {
                "temperature": temperature,
                "num_predict": max_tokens,
            },
        }
        try:
            resp = requests.post(
                f"{self._host}/api/chat",
                json=payload,
                timeout=self._timeout,
            )
            resp.raise_for_status()
            data = resp.json()
        except requests.HTTPError as e:
            # Most common failure mode: model isn't pulled yet
            try:
                detail = resp.json().get("error", "")
            except Exception:
                detail = ""
            raise RuntimeError(
                f"Ollama HTTP error: {e}. {detail or ''}"
                f" — is the model '{self._model}' pulled? "
                f"Run: ollama pull {self._model}"
            )
        except requests.RequestException as e:
            raise RuntimeError(
                f"Ollama unreachable at {self._host} ({e}). "
                "Is `ollama serve` running?"
            )

        msg = data.get("message", {}).get("content", "")
        return (msg or "").strip()
